package net.civeira.phylax.feature.observe.observedembed.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observeddashboard.domain.ObservedDashboardReference;

class DashboardVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property dashboard of observed embed ")
  void test_dashboard_v_o_builder() {
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertEquals("10", DashboardVO.fromReference("10").getDashboardUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("11", DashboardVO.tryFromReference("11").getDashboardUid(),
        "The builder must store the reference value");
    Assertions.assertEquals("12", DashboardVO.tryFromReference("12", fails).getDashboardUid(),
        "The builder must store the reference value");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertThrows(ConstraintException.class, () -> DashboardVO.tryFrom(null));
    Assertions.assertEquals(ObservedDashboardReference.of("one"),
        DashboardVO.from(ObservedDashboardReference.of("one")).getDashboard());
    Assertions.assertThrows(ConstraintException.class, () -> DashboardVO.tryFrom(new Object() {}));
    Assertions.assertEquals("[" + ObservedDashboardReference.of("one") + "]",
        DashboardVO.from(ObservedDashboardReference.of("one")).toString());
  }
}
